658	def batch_update_clients(database, payload):
659	    """执行批量修改，返回 {"updated_count": 去重后的客户数}；非法请求抛 BatchUpdateError。
660	
661	    任一问题都整次拒绝，不写入任何客户。
662	    """
663	    if not isinstance(payload, dict):
664	        raise BatchUpdateError("请求体必须是 JSON 对象")
665	
666	    raw_ids = payload.get("ids")
667	    if not isinstance(raw_ids, list):
668	        raise BatchUpdateError("ids 必须是客户编号数组")
669	    if not raw_ids:
670	        raise BatchUpdateError("未选择客户：请先勾选至少一名客户")
671	
672	    ids = []
673	    seen_ids = set()
674	    for raw_id in raw_ids:
675	        if isinstance(raw_id, bool) or not isinstance(raw_id, int) or raw_id <= 0:
676	            raise BatchUpdateError("客户编号必须是正整数：%r 不合法" % (raw_id,))
677	        if raw_id not in seen_ids:
678	            seen_ids.add(raw_id)
679	            ids.append(raw_id)
680	
681	    raw_updates = payload.get("updates", {})
682	    if not isinstance(raw_updates, dict):
683	        raise BatchUpdateError("updates 必须是字段修改说明对象")
684	    extra = [key for key in raw_updates if key not in OPTIONAL_FIELDS]
685	    if extra:
686	        raise BatchUpdateError("包含不能修改或不存在的字段：%s" % "、".join(extra))
687	
688	    actions = {}
689	    for field_name in OPTIONAL_FIELDS:
690	        spec = raw_updates.get(field_name, {"op": "keep"})
691	        if not isinstance(spec, dict):
692	            raise BatchUpdateError("%s的修改说明必须是对象" % FIELD_LABELS[field_name])
693	        op = spec.get("op")
694	        if op not in ("keep", "set", "clear"):
695	            raise BatchUpdateError(
696	                "%s的操作必须是 keep、set 或 clear 之一" % FIELD_LABELS[field_name])
697	        if op == "keep":
698	            continue
699	        if op == "clear":
700	            actions[field_name] = None
701	        else:
702	            actions[field_name] = _normalize_set_value(field_name, spec.get("value"))
703	
704	    if not actions:
705	        raise BatchUpdateError("全部字段均保持原值：请至少选择一个字段进行设置或清空")
706	
707	    placeholders = ",".join("?" for _ in ids)
708	    existing = {
709	        row[0]
710	        for row in database.execute(
711	            "SELECT id FROM clients WHERE id IN (%s)" % placeholders, ids
712	        )
713	    }
714	    missing = [cid for cid in ids if cid not in existing]
715	    if missing:
716	        raise BatchUpdateError("找不到对应客户，编号：%s" % "、".join(str(c) for c in missing))
717	
718	    assignments = ", ".join("%s = ?" % field_name for field_name in actions)
719	    params = list(actions.values()) + ids
720	    try:
721	        database.execute(
722	            "UPDATE clients SET %s WHERE id IN (%s)" % (assignments, placeholders), params
723	        )
724	        database.commit()
725	    except sqlite3.DatabaseError:
726	        database.rollback()
727	        raise BatchUpdateError("保存失败：数据库错误，本次修改未生效")
728	
729	    return {"updated_count": len(ids)}
