732	def parse_csv(text):
733	    """解析 RFC 4180 风格 CSV，返回 (header, data_rows)。
734	
735	    支持引号包裹的字段、引号内逗号与换行、双引号转义；
736	    引号外支持 LF / CRLF / CR 换行。结构损坏时抛 FileError：
737	    - 未加引号的字段中出现双引号（双引号只能在字段开头用于包住整个字段）；
738	    - 结束引号后出现逗号、换行或文件结束以外的字符（含空格）；
739	    - 文件结束时仍有字段处于引号内（引号未闭合）。
740	    错误信息区分上述三种情况，并指出发生在表头还是第 N 条数据记录
741	    （数据记录编号不包含表头，引号字段内的换行不增加编号）。
742	    """
743	    rows = []
744	    record = []
745	    field = []
746	    quoted = False        # 当前字段处于引号内
747	    started = False       # 当前字段已经开始（已有内容或已进入引号）
748	    closed = False       # 引号字段刚结束，等待逗号 / 换行 / 文件结束
749	    record_number = 0     # 0 = 表头，1 起为数据记录
750	    i = 0
751	    n = len(text)
752	
753	    def location():
754	        return "表头" if record_number == 0 else "第 %d 条数据记录" % record_number
755	
756	    def structure_error(kind):
757	        raise FileError("CSV 结构损坏（%s）：%s" % (location(), kind))
758	
759	    def finish_record():
760	        nonlocal record, field, started, closed
761	        record.append("".join(field))
762	        rows.append(record)
763	        record = []
764	        field = []
765	        started = False
766	        closed = False
767	
768	    while i < n:
769	        c = text[i]
770	        if quoted:
771	            if c == '"':
772	                if i + 1 < n and text[i + 1] == '"':
773	                    field.append('"')
774	                    i += 2
775	                    continue
776	                quoted = False
777	                closed = True
778	                i += 1
779	                continue
780	            if c == "\r":
781	                # 统一字段内换行符为 LF
782	                if i + 1 < n and text[i + 1] == "\n":
783	                    i += 1
784	                field.append("\n")
785	                i += 1
786	                continue
787	            field.append(c)
788	            i += 1
789	            continue
790	        if closed:
791	            # 引号已结束，只允许逗号、记录换行或文件结束
792	            if c == ",":
793	                record.append("".join(field))
794	                field = []
795	                started = False
796	                closed = False
797	            elif c in "\r\n":
798	                if c == "\r" and i + 1 < n and text[i + 1] == "\n":
799	                    i += 1
800	                finish_record()
801	                record_number += 1
802	            else:
803	                structure_error("结束引号后有多余字符，结束引号后只能紧接逗号、记录换行或文件结束")
804	            i += 1
805	            continue
806	        if c == '"' and not started:
807	            quoted = True
808	            started = True
809	        elif c == '"':
810	            structure_error("未加引号的字段中出现双引号，双引号只能在字段开头用于包住整个字段")
811	        elif c == ",":
812	            record.append("".join(field))
813	            field = []
814	            started = False
815	        elif c in "\r\n":
816	            if c == "\r" and i + 1 < n and text[i + 1] == "\n":
817	                i += 1
818	            if not started and not record and not field:
819	                # 空白行：不作为数据记录（显式的 "" 空字段 started=True，仍会保留）
820	                i += 1
821	                continue
822	            finish_record()
823	            record_number += 1
824	        else:
825	            field.append(c)
826	            started = True
827	        i += 1
828	    if quoted:
829	        structure_error("引号未闭合，文件结束时仍有字段处于引号内")
830	    if started or field or record or closed:
831	        record.append("".join(field))
832	        rows.append(record)
833	    if not rows:
834	        raise FileError("CSV 内容为空：缺少表头")
835	    return rows[0], rows[1:]
